package com.umc.pediupatrao.service;
import com.umc.pediupatrao.audit.Auditoria; import com.umc.pediupatrao.audit.AuditoriaService; import com.umc.pediupatrao.entity.Cliente; import com.umc.pediupatrao.repository.ClienteRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ClienteService {private final ClienteRepository repo;private final AuditoriaService auditoria;public ClienteService(ClienteRepository r,AuditoriaService a){repo=r;auditoria=a;} public Cliente novoCliente(Cliente c){return salvar(c);} public List<Cliente> listarClientes(){return repo.findAll();} public void excluir(String id){throw new UnsupportedOperationException("Exclusão de clientes desabilitada para preservar histórico.");} public Optional<Cliente> buscarPorId(String id){return repo.findById(id);} public Cliente salvar(Cliente c){if(c.getId()==null){Cliente novo=repo.save(c);auditoria.registrar("CRIACAO","Cliente",novo.getId(),Map.of("nome",new Auditoria.Alteracao(null,novo.getNome())),null);return novo;}Cliente antigo=repo.findById(c.getId()).orElseThrow(()->new IllegalArgumentException("Cliente não encontrado."));Map<String,Auditoria.Alteracao> alteracoes=new LinkedHashMap<>();comparar(alteracoes,"nome",antigo.getNome(),c.getNome());comparar(alteracoes,"telefone",antigo.getTelefone(),c.getTelefone());comparar(alteracoes,"cep",antigo.getCep(),c.getCep());comparar(alteracoes,"logradouro",antigo.getLogradouro(),c.getLogradouro());comparar(alteracoes,"numero",antigo.getNumero(),c.getNumero());comparar(alteracoes,"complemento",antigo.getComplemento(),c.getComplemento());comparar(alteracoes,"endereco",antigo.getEndereco(),c.getEndereco());comparar(alteracoes,"bairro",antigo.getBairro(),c.getBairro());comparar(alteracoes,"cidade",antigo.getCidade(),c.getCidade());comparar(alteracoes,"estado",antigo.getEstado(),c.getEstado());Cliente salvo=repo.save(c);if(!alteracoes.isEmpty())auditoria.registrar("ALTERACAO","Cliente",salvo.getId(),alteracoes,null);return salvo;}private void comparar(Map<String,Auditoria.Alteracao> m,String k,Object a,Object n){if(!Objects.equals(a,n))m.put(k,new Auditoria.Alteracao(a,n));}}
